import { sep } from 'path';
import type { Configuration, HtmlRspackPluginOptions } from '@rspack/core';
import type {
  BundlerContext,
  BundlerHtmlConfig,
  Target,
} from '@teambit/bundler';
import { rspack } from '@rspack/core';
import { isUndefined, omitBy } from 'lodash';
import CompressionPlugin from 'compression-webpack-plugin';
import { RspackManifestPlugin } from 'rspack-manifest-plugin';
import NodePolyfillPlugin from 'node-polyfill-webpack-plugin';
// import { WebpackBitReporterPlugin } from '@teambit/webpack';
import '@teambit/react.babel.bit-react-transformer';
import { ComponentID } from '@teambit/component-id';
import { mdxOptions } from '@teambit/mdx.modules.mdx-v3-options';

function generateHtmlPlugin(config: BundlerHtmlConfig) {
  const baseConfig: HtmlRspackPluginOptions = {
    filename: config.filename,
    chunks: config.chunks,
    // chunksSortMode: config.chunkOrder,
    title: config.title,
    templateContent: config.templateContent,
    minify: config.minify,
    // cache: false,
    favicon: config.favicon,
  };

  const filteredConfig = omitBy(baseConfig, isUndefined);
  return new rspack.HtmlRspackPlugin(filteredConfig);
}

function generateHtmlPlugins(configs: BundlerHtmlConfig[]) {
  return configs.map((config) => generateHtmlPlugin(config));
}

export function configFactory(
  target: Target,
  context: BundlerContext
): Configuration {
  let truthyEntries =
    Array.isArray(target.entries) && target.entries.length
      ? target.entries.filter(Boolean)
      : target.entries || {};
  if (Array.isArray(truthyEntries) && !truthyEntries.length) {
    truthyEntries = {};
  }

  const htmlConfig = target.html ?? context.html;
  const compress = target.compress ?? context.compress;
  const htmlPlugins = htmlConfig ? generateHtmlPlugins(htmlConfig) : undefined;
  const compressionPlugin = compress ? new CompressionPlugin() : undefined;
  const splitChunks = target.chunking?.splitChunks;
  const outputPath = `${target.outputPath}${sep}public`;
  const isEnvTemplate = context.metaData?.isEnvTemplate;

  const config: Configuration = {
    experiments: {
      css: true,
    },
    mode: 'production',
    devtool: 'source-map',
    // Stop compilation early in production
    bail: true,
    // These are the "entry points" to our application.
    // This means they will be the "root" imports that are included in JS bundle.
    // @ts-ignore
    entry: truthyEntries,

    optimization: {
      minimize: true,
    },
    output: {
      path: outputPath,
      ...(target.filename ? { filename: target.filename } : {}),
      ...(target.chunkFilename ? { chunkFilename: target.chunkFilename } : {}),
      assetModuleFilename: 'static/images/[hash][ext][query]',
      cssFilename: 'static/css/[name].[contenthash:8].css',
      cssChunkFilename: 'static/css/[name].[contenthash:8].chunk.css',
      // output.chunkLoadingGlobal - The global variable is used by webpack for loading chunks.
      // might run into this error, when running multiple chunks created by different webpack builds:
      //    "Uncaught TypeError: __webpack_require__.n is not a function"
      // this is because each build creates its own runtime, and they compete on the same global name.
      // setting a separate global name for the template ensures it will not conflict with preview chunks loaded in runtime
      ...(isEnvTemplate
        ? {
            filename: '[name].[chunkhash].js',
            chunkLoadingGlobal: '__loadChunks_EnvTemplate',
          }
        : {}),
    },
    infrastructureLogging: {
      level: 'error',
    },
    stats: {
      warnings: true,
      errorDetails: true,
    },
    resolve: {
      extensions: ['...', '.ts', '.tsx', '.jsx'],
    },
    module: {
      generator: {
        'css/auto': {
          esModule: false,
          exportsConvention: 'camel-case-only',
          localIdentName: '[name]__[local]-[hash:base64:5]',
        },
        css: {
          esModule: false,
        },
        'css/module': {
          esModule: false,
          exportsConvention: 'camel-case-only',
          localIdentName: '[name]__[local]-[hash:base64:5]',
        },
      },
      parser: {
        // `dashedIdents: false` keeps CSS custom properties (`--token`) GLOBAL.
        // rspack's native CSS modules scope dashed idents by default, so a
        // `var(--button-bg)` reference inside a `.module.css`/`.module.scss`
        // gets rewritten to the locally-hashed `var(--button.module__…-<hash>)`,
        // which no longer matches the unscoped `--button-bg` a theme defines
        // globally — theme tokens stop resolving and components render unstyled.
        // The webpack/`css-loader` pipeline (react-env <= 6.0.14) never scoped
        // custom properties; this restores that behaviour. Class names are still
        // scoped via `customIdents`/`localIdentName`.
        'css/auto': {
          namedExports: false,
          dashedIdents: false,
        },
        css: {
          namedExports: false,
        },
        'css/module': {
          namedExports: false,
          dashedIdents: false,
        },
      },
      rules: [
        {
          test: /\.js$/,
          include: [/node_modules/, /\/dist\//],
          exclude: /@teambit\/legacy/,
          descriptionData: { componentId: ComponentID.isValidObject },
          use: [
            {
              loader: require.resolve('babel-loader'),
              options: {
                sourceType: 'unambiguous',
                inputSourceMap: false,
                sourceMaps: false,
                babelrc: false,
                configFile: false,
                plugins: [
                  [
                    require.resolve(
                      '@teambit/react.babel.bit-react-transformer'
                    ),
                  ],
                ].filter(Boolean),
                // turn off all optimizations (only slow down for node_modules)
                compact: false,
                minified: false,
              },
            },
          ],
        },
        {
          test: /\.jsx$/,
          use: {
            loader: 'builtin:swc-loader',
            options: {
              jsc: {
                parser: {
                  syntax: 'ecmascript',
                  jsx: true,
                },
                transform: {
                  react: {
                    development: false,
                    refresh: false,
                  },
                },
              },
            },
          },
        },
        {
          test: /\.(ts|tsx)$/,
          exclude: [/node_modules/],
          loader: 'builtin:swc-loader',
          options: {
            jsc: {
              parser: {
                syntax: 'typescript',
                tsx: true,
                decorators: true,
              },
            },
          },
          type: 'javascript/auto',
        },
        {
          test: /\.mdx?$/,
          use: [
            {
              loader: require.resolve('babel-loader'),
              options: {
                sourceType: 'unambiguous',
                babelrc: false,
                configFile: false,
                presets: [
                  require.resolve('@babel/preset-env'),
                  require.resolve('@babel/preset-react'),
                ],
              },
            },
            {
              loader: require.resolve('@mdx-js/loader'),
              options: mdxOptions,
            },
            {
              loader: require.resolve('@teambit/mdx.modules.mdx-pre-loader'),
            },
          ],
        },
        {
          test: /\.module\.css$/i,
          type: 'css/module',
        },
        {
          test: /(?<!\.module)\.css$/i,
          type: 'css',
          sideEffects: true,
        },
        {
          test: /\.module\.(scss|sass)$/,
          use: {
            loader: require.resolve('sass-loader'),
            options: {
              sassOptions: {
                quietDeps: true,
                silenceDeprecations: ['legacy-js-api', 'import', 'global-builtin'],
                logger: { warn() {}, debug() {} },
              },
            },
          },
          type: 'css/module',
        },
        {
          test: /(?<!\.module)\.(scss|sass)$/,
          use: {
            loader: require.resolve('sass-loader'),
            options: {
              sassOptions: {
                quietDeps: true,
                silenceDeprecations: ['legacy-js-api', 'import', 'global-builtin'],
                logger: { warn() {}, debug() {} },
              },
            },
          },
          type: 'css',
          sideEffects: true,
        },
        {
          test: /\.(png|jpe?g|gif)$/i,
          type: 'asset/resource',
        },
        {
          test: /\.svg$/,
          type: 'asset',
        },
      ],
    },
    plugins: [
      new rspack.DefinePlugin({
        'process.env.NODE_ENV': JSON.stringify('production'),
      }),
      new rspack.ProvidePlugin({
        process: [require.resolve('process/browser')],
      }),
      new RspackManifestPlugin({
        fileName: 'assets-manifest.json',
        assetHookStage: 5000,
        map: (f) => {
          // eslint-disable-next-line no-param-reassign
          f.path = f.path.replace(/^auto\//, '');
          return f;
        },
      }) as any,
      // rspack treats `node:` as a URI scheme and fails with "Unhandled scheme"
      // before resolve.alias/fallback ever see the request, so NodePolyfillPlugin
      // never applies to `node:`-prefixed imports. Strip the prefix at the
      // module-request level so `node:stream` gets the same polyfill as `stream`.
      // this is the canonical rspack workaround - the same "protocol-imports"
      // NormalModuleReplacementPlugin ships in the official @rsbuild/plugin-node-polyfill,
      // and native alias/fallback support for `node:*` is still an open rspack issue
      // (https://github.com/web-infra-dev/rspack/issues/12666).
      new rspack.NormalModuleReplacementPlugin(/^node:/, (resource) => {
        resource.request = resource.request.replace(/^node:/, '');
      }),
      new NodePolyfillPlugin({
        additionalAliases: ['process'],
      }),
      // new WebpackBitReporterPlugin({
      //   options: { pubsub },
      // }),
    ],
  };

  if (target.runtimeChunkName) {
    config.optimization = config.optimization || {};
    config.optimization.runtimeChunk = {
      name: target.runtimeChunkName,
    };
  }

  if (splitChunks) {
    config.optimization = config.optimization || {};
    config.optimization.splitChunks = {
      chunks: 'all',
      name: false,
    };
  }

  if (htmlPlugins && htmlPlugins.length) {
    if (!config.plugins) {
      config.plugins = [];
    }
    config.plugins = config.plugins.concat(htmlPlugins);
  }

  if (compress) {
    if (!config.plugins) {
      config.plugins = [];
    }
    // @ts-ignore
    config.plugins = config.plugins.concat(compressionPlugin);
  }

  return config;
}
